{
  "requirement_id": "REQ-005",
  "summary": "實作任務狀態流轉 API `POST /api/tasks/{tid}/transition`，支援設定新狀態，並根據狀態機規則驗證流轉合法性、回傳相應的 HTTP 狀態碼。",
  "acceptance_criteria": [
    "允許的狀態流轉包含：todo 轉為 in_progress、in_progress 轉為 done、in_progress 轉為 todo。",
    "done 狀態為終態，任何從 done出發的流轉皆應回傳 409 錯誤且任務狀態保持不變。",
    "其他未列出的流轉（包含 todo 轉為 done 以及相同狀態的流轉）皆應回傳 409 錯誤。",
    "當請求中的 to 參數不是合法的狀態時，應回傳 422 錯誤。"
  ]
}

{
  "summary": "實作任務狀態流轉 API `POST /api/tasks/{tid}/transition`，支援設定新狀態，並根據狀態機規則驗證流轉合法性、回傳相應的 HTTP 狀態碼。",
  "acceptance_criteria": [
    "允許的狀態流轉包含：todo 轉為 in_progress、in_progress 轉為 done、in_progress 轉為 todo。",
    "done 狀態為終態，任何從 done出發的流轉皆應回傳 409 錯誤且任務狀態保持不變。",
    "其他未列出的流轉（包含 todo 轉為 done 以及相同狀態的流轉）皆應回傳 409 錯誤。",
    "當請求中的 to 參數不是合法的狀態時，應回傳 422 錯誤。"
  ]
}

{
  "requirement_id": "REQ-005",
  "cases": [
    {
      "id": "TC-1",
      "title": "Verify allowed transitions: todo to in_progress, in_progress to done, in_progress to todo",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"in_progress\"} for a task in todo status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"done\"} for a task in in_progress status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"todo\"} for a task in in_progress status"
      ],
      "expected": "允許的狀態流轉包含：todo 轉為 in_progress、in_progress 轉為 done、in_progress 轉為 todo。"
    },
    {
      "id": "TC-2",
      "title": "Verify forbidden transition from done status",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"todo\"} for a task in done status"
      ],
      "expected": "done 狀態為終態，任何從 done出發的流轉皆應回傳 409 錯誤且任務狀態保持不變。"
    },
    {
      "id": "TC-3",
      "title": "Verify forbidden transitions for todo to done and self-transitions",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"done\"} for a task in todo status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"todo\"} for a task in todo status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"in_progress\"} for a task in in_progress status",
        "POST /api/tasks/{tid}/transition with body {\"to\": \"done\"} for a task in done status"
      ],
      "expected": "其他未列出的流轉（包含 todo 轉為 done 以及相同狀態的流轉）皆應回傳 409 錯誤。"
    },
    {
      "id": "TC-4",
      "title": "Verify invalid status value in request body",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with body {\"to\": \"invalid_status\"}"
      ],
      "expected": "當請求中的 to 參數不是合法的狀態時，應回傳 422 錯誤。"
    }
  ]
}

